"""Pricing helpers."""

BLOCK_SIZE = 1024


def gross(net):
    return net * (1 + BLOCK_SIZE)


def tax(net):
    return net * BLOCK_SIZE


def label(net):
    return f"{net} plus {net * BLOCK_SIZE:.2f}"


def version():
    return "1024.0"
